import json
import base64

remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(remote.connection_params or '{}')
except Exception:
    cfg = {}

client_id = (cfg.get('applicationId') or '').strip()
client_secret = (cfg.get('applicationSecret') or '').strip()

if not client_id or not client_secret:
    raise Exception("Missing Sencrop credentials: applicationId/applicationSecret")

base = (base_url or '').rstrip('/')

basic = base64.b64encode(
    ('%s:%s' % (client_id, client_secret)).encode('utf-8')
).decode('utf-8')

token_url = base + '/oauth2/token'

token_data = {
    'grant_type': 'client_credentials',
    'scope': 'user',
}

token_headers = {
    'Authorization': 'Basic %s' % basic,
    'Content-Type': 'application/x-www-form-urlencoded',
}

resp = request_retry('POST', token_url, data=token_data, headers=token_headers)

if resp.status_code >= 400:
    raise Exception("Token request failed: %s %s" % (resp.status_code, resp.text))

try:
    token_json = resp.json() or {}
except ValueError:
    raise Exception("Token response is not valid JSON: %s" % resp.text)

token = token_json.get('access_token') or ''
if not token:
    raise Exception("No access_token in token response")

bag['token'] = token

me_url = base + '/me'

me_headers = {
    'Authorization': 'Bearer %s' % token,
    'Accept': 'application/json',
}

resp = request_retry('GET', me_url, headers=me_headers)

if resp.status_code >= 400:
    raise Exception("GET /me failed: %s %s" % (resp.status_code, resp.text))

try:
    me = resp.json() or {}
except ValueError:
    raise Exception("GET /me response is not valid JSON: %s" % resp.text)

bag['me'] = me

partner_id = me.get('item')

if not partner_id:
    raise Exception("Unable to determine partner_id from /me response")

bag['partner_id'] = partner_id

from datetime import timedelta

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
today_str = fields.Date.today()

condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id),
]

if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))

sensors = Sensor.search(condition)
plan = []

for sensor in sensors:
    try:
        cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        cfg = {}

    device_code = (cfg.get('device_id') or '').strip()
    measure = (cfg.get('measure') or '').strip()

    if not device_code or not measure:
        continue

    plan.append({
        'sensor_id': sensor.id,
        'device_id': sensor.device_id.id,
        'device_code': device_code,
        'measure': measure,
    })

bag['sensors_plan'] = plan
